message.content:
{
  "sections": [
    {
      "title": "Why you were in the hospital",
      "bullets": [
        {
          "id": "b1",
          "text": "You had a lung infection caught outside the hospital.",
          "sources": ["p1:L5", "term:CAP"]
        },
        {
          "id": "b2",
          "text": "You also have diabetes (high blood sugar).",
          "sources": ["p1:L5", "term:DM"]
        }
      ]
    },
    {
      "title": "What to do at home",
      "bullets": [
        {
          "id": "b3",
          "text": "Rest and slowly do more activity as you feel able.",
          "sources": ["p1:L13"]
        },
        {
          "id": "b4",
          "text": "Use the breathing tool 10 times each hour while you are awake.",
          "sources": ["p1:L13"]
        },
        {
          "id": "b5",
          "text": "Eat a diet that keeps your carbs steady for diabetes.",
          "sources": ["p1:L14"]
        },
        {
          "id": "b6",
          "text": "Drink plenty of fluids.",
          "sources": ["p1:L14"]
        }
      ]
    },
    {
      "title": "Your follow-up visits",
      "bullets": [
        {
          "id": "b7",
          "text": "See your primary care doctor. Go in 7 to 10 days.",
          "sources": ["p1:L15"]
        },
        {
          "id": "b8",
          "text": "Get a repeat chest x-ray. Go in 6 weeks. This checks your lung infection.",
          "sources": ["p1:L15"]
        }
      ]
    }
  ],
  "questions_for_your_doctor": [
    "When should I stop using the breathing tool?",
    "Do I need any changes to my diabetes medicine?",
    "What symptoms should make me call you sooner?"
  ]
}
